package my.noveldokusha.text_to_speech

import android.graphics.Color
import my.noveldokusha.core.appPreferences.TtsAudioSource

/** Immutable video-export settings. Values are primitive/URI based; image bytes are never persisted. */
data class TtsVideoVisualSettings(
    val paragraphMode: ParagraphDisplayMode = ParagraphDisplayMode.DYNAMIC_CONTEXT,
    val longParagraphMode: LongParagraphMode = LongParagraphMode.AUTO_FIT,
    val width: Int = 1920, val height: Int = 1080, val fps: Int = 30,
    val fontSizePx: Float = 54f, val minFontSizePx: Float = 30f, val lineSpacingMultiplier: Float = 1.15f,
    val paragraphSpacingPx: Float = 28f, val letterSpacingEm: Float = 0f, val textColor: Int = Color.WHITE,
    val bold: Boolean = false, val italic: Boolean = false,
    val horizontalAlignment: VideoTextAlignment = VideoTextAlignment.CENTER,
    val verticalPositionFraction: Float = .50f,
    val horizontalMarginFraction: Float = .09f,
    val verticalMarginFraction: Float = .07f,
    val cardEnabled: Boolean = true, val cardColor: Int = 0xD2141418.toInt(), val cardAlpha: Float = .82f,
    val cardCornerRadiusPx: Float = 28f, val cardPaddingPx: Float = 30f, val cardStrokeWidthPx: Float = 1.5f, val cardStrokeColor: Int = 0x50FFFFFF.toInt(),
    val highlightColor: Int = 0xFFFFD24B.toInt(), val highlightAlpha: Float = .92f, val highlightCornerRadiusPx: Float = 8f, val highlightPaddingPx: Float = 4f,
    val safeMarginPx: Float = 80f, val maxTextWidthFraction: Float = .82f,
    val artworkMode: ArtworkMode = ArtworkMode.NONE, val backgroundMode: BackgroundMode = BackgroundMode.SOLID, val backgroundColor: Int = 0xFF121216.toInt(), val backgroundUri: String = "",
    val artworkUris: List<String> = emptyList(), val artworkWidthPx: Float = 260f, val artworkOpacity: Float = .95f, val artworkCornerRadiusPx: Float = 24f,
    val artworkBorderWidthPx: Float = 0f, val artworkBorderColor: Int = Color.TRANSPARENT, val artworkOverlay: Boolean = false,
    val slideshowEnabled: Boolean = false, val slideshowIntervalMode: SlideshowIntervalMode = SlideshowIntervalMode.PERCENT_OF_TOTAL_DURATION,
    val slideshowIntervalMs: Long = 8_000L, val randomIntervalMinMs: Long = 4_000L, val randomIntervalMaxMs: Long = 12_000L,
    val slideshowTransition: SlideshowTransition = SlideshowTransition.CROSSFADE, val transitionDurationMs: Long = 700L,
    val slideshowSeed: Long = 0L,
)

enum class ParagraphDisplayMode { CURRENT_ONLY, CURRENT_WITH_CONTEXT, DYNAMIC_CONTEXT }
enum class LongParagraphMode { AUTO_FIT, SMOOTH_SCROLL }
enum class ArtworkMode { NONE, LEFT, RIGHT, BOTH }
enum class BackgroundMode { SOLID, PRESET, IMAGE }
enum class SlideshowIntervalMode { FIXED_INTERVAL, PERCENT_OF_TOTAL_DURATION, RANDOM_INTERVAL }
enum class SlideshowTransition { NONE, FADE, CROSSFADE, SUBTLE_SLIDE, SUBTLE_ZOOM }
enum class TimelineTimingMode { EXACT, APPROXIMATE }
enum class VideoTextAlignment { LEFT, CENTER, RIGHT }

data class VideoParagraph(val id:String,val displayText:String,val preparedText:String,val startUs:Long,val endUs:Long,val blockIndex:Int,val chunkIndex:Int=0,val timingMode:TimelineTimingMode=TimelineTimingMode.EXACT,val spokenRanges:List<VideoSpokenRange> = emptyList())
data class VideoSpokenRange(val startUs:Long,val endUs:Long,val preparedStart:Int,val preparedEnd:Int,val displayStart:Int,val displayEnd:Int,val timingMode:TimelineTimingMode)
data class TtsVideoTimeline(val paragraphs:List<VideoParagraph>,val durationUs:Long,val timingMode:TimelineTimingMode){init{require(durationUs>=0);require(paragraphs.zipWithNext().all{(a,b)->a.endUs<=b.startUs})};fun paragraphAt(t:Long):VideoParagraph?=paragraphs.firstOrNull{t in it.startUs until it.endUs}?:paragraphs.lastOrNull{t>=it.endUs};fun activeRangeAt(t:Long):VideoSpokenRange?=paragraphAt(t)?.spokenRanges?.firstOrNull{t in it.startUs until it.endUs}}

data class TtsVideoRequest(
    val jobId:String,val novelUrl:String,val novelTitle:String,val chapterUrl:String,val chapterIndex:Int,val chapterTitle:String,
    val source:TtsAudioSource,val translationSourceLang:String="",val translationTargetLang:String="",val enginePackage:String,val voiceId:String,val speed:Float,val pitch:Float,
    val visual:TtsVideoVisualSettings,val outputDirectoryUri:String,
)

fun TtsVideoRequest.serialize():String=org.json.JSONObject().apply{put("jobId",jobId);put("novelUrl",novelUrl);put("novelTitle",novelTitle);put("chapterUrl",chapterUrl);put("chapterIndex",chapterIndex);put("chapterTitle",chapterTitle);put("source",source.name);put("translationSourceLang",translationSourceLang);put("translationTargetLang",translationTargetLang);put("enginePackage",enginePackage);put("voiceId",voiceId);put("speed",speed);put("pitch",pitch);put("outputDirectoryUri",outputDirectoryUri);put("visual",visual.toJson())}.toString()
fun TtsVideoVisualSettings.toJson():org.json.JSONObject=org.json.JSONObject().apply{put("paragraphMode",paragraphMode.name);put("longParagraphMode",longParagraphMode.name);put("width",width);put("height",height);put("fps",fps);put("fontSizePx",fontSizePx);put("minFontSizePx",minFontSizePx);put("lineSpacingMultiplier",lineSpacingMultiplier);put("paragraphSpacingPx",paragraphSpacingPx);put("letterSpacingEm",letterSpacingEm);put("textColor",textColor);put("bold",bold);put("italic",italic);put("horizontalAlignment",horizontalAlignment.name);put("verticalPositionFraction",verticalPositionFraction);put("horizontalMarginFraction",horizontalMarginFraction);put("verticalMarginFraction",verticalMarginFraction);put("cardEnabled",cardEnabled);put("cardColor",cardColor);put("cardAlpha",cardAlpha);put("cardCornerRadiusPx",cardCornerRadiusPx);put("cardPaddingPx",cardPaddingPx);put("cardStrokeWidthPx",cardStrokeWidthPx);put("cardStrokeColor",cardStrokeColor);put("highlightColor",highlightColor);put("highlightAlpha",highlightAlpha);put("highlightCornerRadiusPx",highlightCornerRadiusPx);put("highlightPaddingPx",highlightPaddingPx);put("safeMarginPx",safeMarginPx);put("maxTextWidthFraction",maxTextWidthFraction);put("artworkMode",artworkMode.name);put("backgroundMode",backgroundMode.name);put("backgroundColor",backgroundColor);put("backgroundUri",backgroundUri);put("artworkUris",org.json.JSONArray(artworkUris));put("artworkWidthPx",artworkWidthPx);put("artworkOpacity",artworkOpacity);put("artworkCornerRadiusPx",artworkCornerRadiusPx);put("artworkBorderWidthPx",artworkBorderWidthPx);put("artworkBorderColor",artworkBorderColor);put("artworkOverlay",artworkOverlay);put("slideshowEnabled",slideshowEnabled);put("slideshowIntervalMode",slideshowIntervalMode.name);put("slideshowIntervalMs",slideshowIntervalMs);put("randomIntervalMinMs",randomIntervalMinMs);put("randomIntervalMaxMs",randomIntervalMaxMs);put("slideshowTransition",slideshowTransition.name);put("transitionDurationMs",transitionDurationMs);put("slideshowSeed",slideshowSeed)}
fun String.toTtsVideoRequest():TtsVideoRequest?=runCatching{val o=org.json.JSONObject(this);val v=o.getJSONObject("visual");TtsVideoRequest(o.getString("jobId"),o.getString("novelUrl"),o.getString("novelTitle"),o.getString("chapterUrl"),o.getInt("chapterIndex"),o.getString("chapterTitle"),TtsAudioSource.valueOf(o.getString("source")),o.optString("translationSourceLang"),o.optString("translationTargetLang"),o.getString("enginePackage"),o.getString("voiceId"),o.getDouble("speed").toFloat(),o.getDouble("pitch").toFloat(),v.toVisualSettings(),o.getString("outputDirectoryUri"))}.getOrNull()
private fun org.json.JSONObject.toVisualSettings()=TtsVideoVisualSettings(
    paragraphMode=runCatching{ParagraphDisplayMode.valueOf(optString("paragraphMode"))}.getOrDefault(ParagraphDisplayMode.DYNAMIC_CONTEXT),longParagraphMode=runCatching{LongParagraphMode.valueOf(optString("longParagraphMode"))}.getOrDefault(LongParagraphMode.AUTO_FIT),width=optInt("width",1920),height=optInt("height",1080),fps=optInt("fps",30),fontSizePx=optDouble("fontSizePx",54.0).toFloat(),minFontSizePx=optDouble("minFontSizePx",30.0).toFloat(),lineSpacingMultiplier=optDouble("lineSpacingMultiplier",1.15).toFloat(),paragraphSpacingPx=optDouble("paragraphSpacingPx",28.0).toFloat(),letterSpacingEm=optDouble("letterSpacingEm",0.0).toFloat(),textColor=optInt("textColor",Color.WHITE),bold=optBoolean("bold",false),italic=optBoolean("italic",false),horizontalAlignment=runCatching{VideoTextAlignment.valueOf(optString("horizontalAlignment"))}.getOrDefault(VideoTextAlignment.CENTER),verticalPositionFraction=optDouble("verticalPositionFraction",.50).toFloat(),horizontalMarginFraction=optDouble("horizontalMarginFraction",.09).toFloat(),verticalMarginFraction=optDouble("verticalMarginFraction",.07).toFloat(),cardEnabled=optBoolean("cardEnabled",true),cardColor=optInt("cardColor",Color.DKGRAY),cardAlpha=optDouble("cardAlpha",.82).toFloat(),cardCornerRadiusPx=optDouble("cardCornerRadiusPx",28.0).toFloat(),cardPaddingPx=optDouble("cardPaddingPx",30.0).toFloat(),cardStrokeWidthPx=optDouble("cardStrokeWidthPx",1.5).toFloat(),cardStrokeColor=optInt("cardStrokeColor",Color.TRANSPARENT),highlightColor=optInt("highlightColor",Color.YELLOW),highlightAlpha=optDouble("highlightAlpha",.92).toFloat(),highlightCornerRadiusPx=optDouble("highlightCornerRadiusPx",8.0).toFloat(),highlightPaddingPx=optDouble("highlightPaddingPx",4.0).toFloat(),safeMarginPx=optDouble("safeMarginPx",80.0).toFloat(),maxTextWidthFraction=optDouble("maxTextWidthFraction",.82).toFloat(),artworkMode=runCatching{ArtworkMode.valueOf(optString("artworkMode"))}.getOrDefault(ArtworkMode.NONE),backgroundMode=runCatching{BackgroundMode.valueOf(optString("backgroundMode"))}.getOrDefault(BackgroundMode.SOLID),backgroundColor=optInt("backgroundColor",Color.DKGRAY),backgroundUri=optString("backgroundUri"),artworkUris=buildList{val a=optJSONArray("artworkUris")?:return@buildList;for(i in 0 until a.length())add(a.getString(i))},artworkWidthPx=optDouble("artworkWidthPx",260.0).toFloat(),artworkOpacity=optDouble("artworkOpacity",.95).toFloat(),artworkCornerRadiusPx=optDouble("artworkCornerRadiusPx",24.0).toFloat(),artworkBorderWidthPx=optDouble("artworkBorderWidthPx",0.0).toFloat(),artworkBorderColor=optInt("artworkBorderColor",Color.TRANSPARENT),artworkOverlay=optBoolean("artworkOverlay",false),slideshowEnabled=optBoolean("slideshowEnabled",false),slideshowIntervalMode=runCatching{SlideshowIntervalMode.valueOf(optString("slideshowIntervalMode"))}.getOrDefault(SlideshowIntervalMode.PERCENT_OF_TOTAL_DURATION),slideshowIntervalMs=optLong("slideshowIntervalMs",8000),randomIntervalMinMs=optLong("randomIntervalMinMs",4000),randomIntervalMaxMs=optLong("randomIntervalMaxMs",12000),slideshowTransition=runCatching{SlideshowTransition.valueOf(optString("slideshowTransition"))}.getOrDefault(SlideshowTransition.CROSSFADE),transitionDurationMs=optLong("transitionDurationMs",700),slideshowSeed=optLong("slideshowSeed",0))
